import{_ as t,c as n,o,a5 as a,j as l,aD as i,aE as r}from"./chunks/framework.BmNIwhaK.js";const y=JSON.parse('{"title":"Collection Management and Batch Execution","description":"Guide to configuring SyncETA Collections to group multiple unit scenarios and execute them sequentially or in parallel.","frontmatter":{"title":"Collection Management and Batch Execution","description":"Guide to configuring SyncETA Collections to group multiple unit scenarios and execute them sequentially or in parallel.","head":[["meta",{"name":"keywords","content":"SyncETA, Collection, Batch Execution, Cross-Browser Testing, Scenario Grouping, Test Suite"}],["meta",{"property":"og:title","content":"Collection Management and Batch Execution | Empasy Docs"}],["meta",{"property":"og:description","content":"Guide to configuring SyncETA Collections to group multiple unit scenarios and execute them sequentially or in parallel."}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/synceta/collection"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/collection"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/collection"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/collection"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/collection"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/synceta/collection"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Collection Management and Batch Execution | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Guide to configuring SyncETA Collections to group multiple unit scenarios and execute them sequentially or in parallel."}]],"sort":500},"headers":[],"relativePath":"en/synceta/collection.md","filePath":"en/synceta/collection.md","lastUpdated":1795293539000}'),c={name:"en/synceta/collection.md"};function s(d,e,h,u,g,m){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="collection-management-and-batch-execution" tabindex="-1">Collection Management and Batch Execution <a class="header-anchor" href="#collection-management-and-batch-execution" aria-label="Permalink to “Collection Management and Batch Execution”">​</a></h1><p>A <strong>Collection</strong> lets you group related test scenarios together to manage and run them in batches as a single Test Suite.</p><hr><h2 id="_1-key-use-cases-for-collections" tabindex="-1">1. Key Use Cases for Collections <a class="header-anchor" href="#_1-key-use-cases-for-collections" aria-label="Permalink to “1. Key Use Cases for Collections”">​</a></h2><ul><li><strong>Sequential End-to-End Batch Verification</strong>: Verify individual scenarios consecutively in order, such as Login -&gt; Browse Products -&gt; Checkout &amp; Payment -&gt; Order Cancellation.</li><li><strong>Concurrent Multi-Browser Parallel Execution</strong>: Run the same scenario set simultaneously across multiple browser environments—such as Chrome, Firefox, and Edge—to validate cross-browser compatibility.</li></ul><hr><h2 id="_2-how-to-create-a-collection" tabindex="-1">2. How to Create a Collection <a class="header-anchor" href="#_2-how-to-create-a-collection" aria-label="Permalink to “2. How to Create a Collection”">​</a></h2><h3 id="step-1-navigate-to-collections-and-create-a-new-one" tabindex="-1">Step 1: Navigate to Collections and Create a New One <a class="header-anchor" href="#step-1-navigate-to-collections-and-create-a-new-one" aria-label="Permalink to “Step 1: Navigate to Collections and Create a New One”">​</a></h3><p>Select <strong>&#39;Collections&#39;</strong> from the left navigation menu, then click the <strong>&#39;New Collection&#39;</strong> button in the upper-right corner.</p><p><img src="'+i+'" alt="Create collection menu" loading="lazy"></p><h3 id="step-2-select-scenarios-and-define-execution-order" tabindex="-1">Step 2: Select Scenarios and Define Execution Order <a class="header-anchor" href="#step-2-select-scenarios-and-define-execution-order" aria-label="Permalink to “Step 2: Select Scenarios and Define Execution Order”">​</a></h3><p>Check the scenarios you want to include in the collection and drag and drop them to arrange their execution order.</p><p><img src="'+r+'" alt="Select scenarios and set execution order" loading="lazy"></p><hr><h2 id="_3-collection-execution-modes-and-strategy-comparison" tabindex="-1">3. Collection Execution Modes and Strategy Comparison <a class="header-anchor" href="#_3-collection-execution-modes-and-strategy-comparison" aria-label="Permalink to “3. Collection Execution Modes and Strategy Comparison”">​</a></h2><p>Depending on your testing goals and CI/CD pipeline stage, you can run a collection in either of two execution modes.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Execution Mode</th><th style="text-align:left;">Behavior</th><th style="text-align:center;">Session &amp; Cookie Sharing</th><th style="text-align:left;">Primary Use Cases</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Sequential Mode</strong></td><td style="text-align:left;">Executes scenarios one by one in the specified order (<code>1 -&gt; 2 -&gt; 3</code>)</td><td style="text-align:center;">Isolated or selectively preserved</td><td style="text-align:left;">Smoke tests and business flows with sequential data dependencies</td></tr><tr><td style="text-align:left;"><strong>Parallel Mode</strong></td><td style="text-align:left;">Runs scenarios and multiple browsers (<code>Chromium</code>, <code>Firefox</code>, <code>WebKit</code>) concurrently across Playwright workers</td><td style="text-align:center;">Fully isolated per scenario</td><td style="text-align:left;">Large-scale nightly regression tests and cross-browser compatibility checks</td></tr></tbody></table><hr><h2 id="_4-collection-execution-and-result-aggregation" tabindex="-1">4. Collection Execution and Result Aggregation <a class="header-anchor" href="#_4-collection-execution-and-result-aggregation" aria-label="Permalink to “4. Collection Execution and Result Aggregation”">​</a></h2><p>When a collection runs, pass/fail status for each scenario is aggregated in real time. Once the entire collection finishes, a comprehensive summary report is recorded on the dashboard.</p>',20),l("iframe",{width:"100%",height:"400",src:"https://www.youtube.com/embed/dsb0XpGy7A0",frameborder:"0",allowfullscreen:"",allow:"autoplay; encrypted-media"},null,-1)])])}const f=t(c,[["render",s]]);export{y as __pageData,f as default};
